SELECT COUNT(*) FROM (SELECT trip_id, hack_license, pu_location_id, fare_amount, trip_distance FROM (SELECT trip_id, hack_license, pu_location_id, fare_amount, trip_distance, ROW_NUMBER() OVER (PARTITION BY hack_license ORDER BY trip_id NULLS LAST) AS _rn FROM trips) AS _t WHERE _rn <= 50) AS t JOIN taxi_zones AS z ON t.pu_location_id = z.location_id WHERE z.borough = 'Manhattan'
